<?php
declare(strict_types=1);
final class InventoryService {
 public static function move(PDO $p,int $batch,int $warehouse,int $delta,string $type,string $reason,int $user,?string $ref=null):int{if(!$delta)throw new DomainException('Quantity change cannot be zero.');$q=$p->prepare('SELECT quantity FROM stock_levels WHERE batch_id=? AND warehouse_id=? FOR UPDATE');$q->execute([$batch,$warehouse]);$row=$q->fetch();$before=(int)($row['quantity']??0);$after=$before+$delta;if($after<0)throw new DomainException("Only $before units are available.");if($row)$p->prepare('UPDATE stock_levels SET quantity=?,updated_at=NOW() WHERE batch_id=? AND warehouse_id=?')->execute([$after,$batch,$warehouse]);else$p->prepare('INSERT INTO stock_levels(batch_id,warehouse_id,quantity) VALUES(?,?,?)')->execute([$batch,$warehouse,$after]);$p->prepare('INSERT INTO stock_movements(batch_id,warehouse_id,type,quantity_change,balance_after,reason,reference,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$batch,$warehouse,$type,$delta,$after,$reason,$ref,$user]);$q=$p->prepare('SELECT item_id FROM batches WHERE id=?');$q->execute([$batch]);AlertService::sync($p,(int)$q->fetchColumn());return $after;}
}
